// Fails the build if the deploy config generated by `vite build` (dist/jazz_setlist/wrangler.json, which
// `wrangler deploy` uses) sets any vars. The app has none in production; DEV_AUTH_EMAIL in particular is a trusted
// stand-in for Cloudflare Access sign-in and must only ever come from a local .env. Run by `check` and `release`.
import { readFileSync } from 'node:fs'

const config = JSON.parse(readFileSync(new URL('../dist/jazz_setlist/wrangler.json', import.meta.url), 'utf8'))
const vars = Object.keys(config.vars ?? {})
if (vars.length) {
  console.error(`dist/jazz_setlist/wrangler.json sets vars (${vars.join(', ')}); a production build must not. Was E2E set?`)
  process.exit(1)
}
console.log('wrangler.json: no vars')
